-- Tend · db/app.sqlite · schema v1
-- Scope v1: notes, tasks, people, timers. Calendar, events and reminders come later
-- (see docs/later/calendar-design-spec-doc.md); they will arrive as a migration to schema_version 2.
--
-- Conventions
--   * ids are ULIDs stored as TEXT (sortable by creation time, generated by the app)
--   * moments in time are INTEGER milliseconds since the Unix epoch, UTC  (*_at columns)
--   * local calendar values stay TEXT: dates 'YYYY-MM-DD', times 'HH:MM' (24h)
--     (a due date or birthday is a day, not a moment; it must not shift with time zones)
--   * booleans are INTEGER 0/1; colors are '#rrggbb'
--   * every table is STRICT (SQLite >= 3.37); open with PRAGMA foreign_keys = ON
--   * paths are relative: notes to <vault>/notes/, attachments to <vault>/.attachments/,
--     task folders to the task root ('' = root, 'work', 'work/tend v0.1')

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

-------------------------------------------------------------------------------
-- 0. App identity and version (the "incompatible db" check reads this)
-------------------------------------------------------------------------------
-- On open: app_id must be 'tend'; schema_version lower than the app's → migrate up;
-- other app_id, higher version or missing table → "An incompatible database exists in db/app.sqlite"
CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
) STRICT;
INSERT INTO meta (key, value) VALUES
  ('app_id', 'tend'),
  ('schema_version', '1'),
  ('created_at', CAST(unixepoch('subsec') * 1000 AS INTEGER));

-- Key/value settings (value is JSON): ui.nav_open, notes.wide, tasks.wide, tasks.layout,
-- tasks.root_name, quick.last_path.note|task|folder, notify.sound, timers.sound, …
CREATE TABLE settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 1. Tags (shared by notes and tasks)
-------------------------------------------------------------------------------
CREATE TABLE tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 2. Notes (content lives in markdown files; these tables are an index of notes/)
-------------------------------------------------------------------------------
-- The files on disk are the source of truth; note_folders + notes mirror them.
--   vault open  → walk notes/: upsert every folder into note_folders and every .md into notes;
--                 folders/files no longer on disk get missing_at (purged after a grace period)
--   app running → a file watcher applies outside changes (Finder, other editors) the same way
--   inside Tend → every create / rename / move / delete writes to disk first, then here
--   mismatch    → the next scan makes the database match the disk
-- Same folder model as tasks: folders keyed by path, items point at their folder, and renaming a
-- folder is one UPDATE on note_folders (ON UPDATE CASCADE moves the notes with it).
-- Renaming 'work' → 'job': UPDATE note_folders SET path = 'job' || substr(path, 5)
--   WHERE path = 'work' OR path LIKE 'work/%';
CREATE TABLE note_folders (
  path       TEXT PRIMARY KEY,           -- '' (= notes/ itself), 'work', 'work/tend v0.1'
  created_at INTEGER NOT NULL,
  missing_at INTEGER                     -- folder disappeared from disk
) STRICT;
INSERT INTO note_folders (path, created_at) VALUES ('', CAST(unixepoch('subsec') * 1000 AS INTEGER));

-- A note's id never changes on rename/move, so tags and attachments follow it.
-- Full path on disk: notes/ || (folder = '' ? '' : folder || '/') || file_name
CREATE TABLE notes (
  id          TEXT PRIMARY KEY,
  folder      TEXT NOT NULL REFERENCES note_folders(path) ON UPDATE CASCADE ON DELETE RESTRICT,
  file_name   TEXT NOT NULL,             -- 'Meeting notes.md'
  title       TEXT NOT NULL,             -- first H1 or file name, for search
  created_at  INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,          -- file mtime
  missing_at  INTEGER,                   -- file disappeared; purge after a grace period
  UNIQUE (folder, file_name)
) STRICT;
CREATE INDEX notes_folder ON notes(folder);   -- folder list: folder = ? OR folder LIKE ? || '/%'

CREATE TABLE note_tags (
  note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
  tag_id  TEXT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
  PRIMARY KEY (note_id, tag_id)
) STRICT;

-------------------------------------------------------------------------------
-- 3. People (own section; birthdays shown in the list, task assignees)
-------------------------------------------------------------------------------
CREATE TABLE people (
  id                TEXT PRIMARY KEY,
  first_name        TEXT NOT NULL,
  last_name         TEXT NOT NULL DEFAULT '',
  nickname          TEXT,                  -- shown instead of first + last when set
  dob_year          INTEGER,               -- optional: birthday known, year unknown
  dob_month         INTEGER CHECK (dob_month BETWEEN 1 AND 12),
  dob_day           INTEGER CHECK (dob_day BETWEEN 1 AND 31),
  tob               TEXT CHECK (tob IS NULL OR tob GLOB '[0-2][0-9]:[0-5][0-9]'),
  notes             TEXT NOT NULL DEFAULT '',
  birthday_reminder INTEGER NOT NULL DEFAULT 1 CHECK (birthday_reminder IN (0, 1)),   -- stored now, hidden in v1 UI; used when reminders arrive
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL,
  CHECK ((dob_month IS NULL) = (dob_day IS NULL))
) STRICT;
CREATE INDEX people_name ON people(first_name COLLATE NOCASE, last_name COLLATE NOCASE);

-- Phones, emails, addresses: any number of each, value + label ('personal', 'work', …)
CREATE TABLE person_contacts (
  id         TEXT PRIMARY KEY,
  person_id  TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('phone', 'email', 'address')),
  value      TEXT NOT NULL,
  label      TEXT NOT NULL DEFAULT '',
  position   INTEGER NOT NULL,           -- order within (person, kind); first = primary
  created_at INTEGER NOT NULL
) STRICT;
CREATE INDEX person_contacts_person ON person_contacts(person_id, kind, position);

-------------------------------------------------------------------------------
-- 4. Task statuses (app-wide; Settings → Tasks)
-------------------------------------------------------------------------------
-- NOT_STARTED always first, DONE always last; defaults can be renamed, never deleted.
-- Reserved values (any case) can't be reused for custom statuses (checked in the app).
CREATE TABLE statuses (
  value      TEXT PRIMARY KEY CHECK (value = upper(value) AND value GLOB '[A-Z]*'),
  label      TEXT NOT NULL UNIQUE COLLATE NOCASE,
  color      TEXT NOT NULL CHECK (color GLOB '#[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]'),
  position   INTEGER NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1))
) STRICT;
INSERT INTO statuses (value, label, color, position, is_default) VALUES
  ('NOT_STARTED', 'Not started', '#7d8995', 0,    1),
  ('IN_PROGRESS', 'In progress', '#1259d3', 1,    1),
  ('DONE',        'Done',        '#1e7a55', 1000, 1);

-------------------------------------------------------------------------------
-- 5. Tasks
-------------------------------------------------------------------------------
-- Folders are identified by path; one root ('') whose display name is settings.tasks.root_name.
-- Renaming 'work' → 'job': UPDATE task_folders SET path = 'job' || substr(path, 5)
--   WHERE path = 'work' OR path LIKE 'work/%';   tasks.path follows via ON UPDATE CASCADE.
-- Explorer sorts folders alphabetically (no manual order).
CREATE TABLE task_folders (
  path       TEXT PRIMARY KEY,           -- '' (root), 'work', 'work/tend v0.1'
  created_at INTEGER NOT NULL
) STRICT;
INSERT INTO task_folders (path, created_at) VALUES ('', CAST(unixepoch('subsec') * 1000 AS INTEGER));

CREATE TABLE tasks (
  id           TEXT PRIMARY KEY,
  path         TEXT NOT NULL REFERENCES task_folders(path) ON UPDATE CASCADE ON DELETE RESTRICT,
  parent_id    TEXT REFERENCES tasks(id) ON DELETE CASCADE,       -- subtask of …
  title        TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'NOT_STARTED'
               REFERENCES statuses(value) ON UPDATE CASCADE ON DELETE RESTRICT,   -- in use → can't delete
  description  TEXT NOT NULL DEFAULT '',                          -- markdown
  due_date     TEXT CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  due_time     TEXT CHECK (due_time IS NULL OR due_time GLOB '[0-2][0-9]:[0-5][0-9]'),
  assignee_id  TEXT REFERENCES people(id) ON DELETE SET NULL,
  order_key    TEXT NOT NULL,            -- one global fractional index (list, board, My day)
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  completed_at INTEGER                   -- set when status becomes DONE
) STRICT;
CREATE INDEX tasks_path     ON tasks(path);                       -- folder lists: path = ? OR path LIKE ? || '/%'
CREATE INDEX tasks_parent   ON tasks(parent_id);
CREATE INDEX tasks_status   ON tasks(status);
CREATE INDEX tasks_due      ON tasks(due_date, due_time) WHERE due_date IS NOT NULL;   -- range: due_date BETWEEN ? AND ?
CREATE INDEX tasks_assignee ON tasks(assignee_id) WHERE assignee_id IS NOT NULL;
CREATE INDEX tasks_order    ON tasks(order_key);

-- Defaults can't be deleted
CREATE TRIGGER statuses_keep_defaults BEFORE DELETE ON statuses
WHEN OLD.is_default = 1
BEGIN SELECT RAISE(ABORT, 'default status cannot be deleted'); END;

-- My day: tasks due today are in by default; rows are manual overrides for a given day
CREATE TABLE my_day (
  task_id  TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  day      TEXT NOT NULL,              -- 'YYYY-MM-DD'
  included INTEGER NOT NULL CHECK (included IN (0, 1)),
  PRIMARY KEY (task_id, day)
) STRICT;

CREATE TABLE task_tags (
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  tag_id  TEXT NOT NULL REFERENCES tags(id)  ON DELETE CASCADE,
  PRIMARY KEY (task_id, tag_id)
) STRICT;

CREATE TABLE task_comments (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  body       TEXT NOT NULL,              -- markdown
  created_at INTEGER NOT NULL,
  edited_at  INTEGER
) STRICT;
CREATE INDEX task_comments_task ON task_comments(task_id, created_at);

-------------------------------------------------------------------------------
-- 6. Attachments (file in .attachments/, metadata here, always referenced by id)
-------------------------------------------------------------------------------
CREATE TABLE attachments (
  id            TEXT PRIMARY KEY,
  original_name TEXT NOT NULL,           -- 'invoice march.pdf' (display / download name)
  stored_name   TEXT NOT NULL UNIQUE,    -- '<id>.pdf' inside .attachments/
  mime_type     TEXT NOT NULL,
  size_bytes    INTEGER NOT NULL,
  sha256        TEXT NOT NULL,
  created_at    INTEGER NOT NULL
) STRICT;

-- Where it's used. A note can also be attached to a task (kind = 'note').
CREATE TABLE attachment_links (
  id            TEXT PRIMARY KEY,
  owner_type    TEXT NOT NULL CHECK (owner_type IN ('task', 'note', 'comment', 'person')),
  owner_id      TEXT NOT NULL,
  kind          TEXT NOT NULL CHECK (kind IN ('file', 'note')),
  attachment_id TEXT REFERENCES attachments(id) ON DELETE CASCADE,
  note_id       TEXT REFERENCES notes(id) ON DELETE CASCADE,
  created_at    INTEGER NOT NULL,
  CHECK ((kind = 'file' AND attachment_id IS NOT NULL AND note_id IS NULL)
      OR (kind = 'note' AND note_id IS NOT NULL AND attachment_id IS NULL))
) STRICT;
CREATE INDEX attachment_links_owner ON attachment_links(owner_type, owner_id);

-------------------------------------------------------------------------------
-- 7. Timers
-------------------------------------------------------------------------------
-- No background process. The window does the work:
--   create  → insert (title, ends_at, state 'running')
--   display → countdown = ends_at - now, recomputed every second (never decremented, so it
--             stays right after sleep or throttling)
--   fire    → when now >= ends_at: desktop notification (+ sound), state = 'rung'
--   +1m / snooze → update ends_at;  cancel → state = 'cancelled'
--   on launch, running timers already past ends_at are shown once as "finished while closed"
CREATE TABLE timers (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL DEFAULT '',
  ends_at    INTEGER NOT NULL,
  state      TEXT NOT NULL DEFAULT 'running' CHECK (state IN ('running', 'rung', 'cancelled')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX timers_running ON timers(state, ends_at);

-------------------------------------------------------------------------------
-- 8. Feedback
-------------------------------------------------------------------------------
CREATE TABLE feedback (
  id          TEXT PRIMARY KEY,
  kind        TEXT NOT NULL CHECK (kind IN ('bug', 'idea', 'other')),
  body        TEXT NOT NULL,
  app_version TEXT NOT NULL,
  created_at  INTEGER NOT NULL
) STRICT;
